27:     // If auth headers are present use them to authenticate...
28:     if (req.headers.authorization && req.headers.authorization.search('Basic ') === 0) {
29:       var userpass = new Buffer(req.headers.authorization.split(' ')[1], 'base64').toString().split(":")
30:       var username = userpass[0];
31:       var password = userpass[1];
