46:     /* Authentication OR authorization failed. Return Auth required
47:      * Headers, delayed for 1 second, if authentication failed. */
48:     res.header('WWW-Authenticate', 'Basic realm="Protected Area"');
49:     if (req.headers.authorization) {
50:       setTimeout(function () {
51:         res.send('Authentication required', 401);
52:       }, 1000);
53:     } else {
54:       res.send('Authentication required', 401);
55:     }
56:   }
